import { defineConfig, devices } from '@playwright/test';

/**
 * Gate 4 (final quality gate): Excel-derived subsystem tests generated by skill 03.
 * Run from the repository root:
 *   npx playwright test --config .ai-dlc/tools/playwright.subsystem.config.ts
 *
 * The JSON report path is injected by gate-runner through PLAYWRIGHT_JSON_OUTPUT_FILE, and Gate 4
 * passes a free port of its own through AIDLC_SUBSYSTEM_PORT. An existing server is never reused:
 * the gate must test the working tree, not whatever is already listening on the port (issue #17).
 */
const port = Number(process.env['AIDLC_SUBSYSTEM_PORT'] ?? 4310);
const device = {
  ...devices['Desktop Chrome'],
  viewport: { width: 800, height: 480 },
  hasTouch: true,
};
// Mutation check of Gate 4 (once per run): one project per mutant, see lib/mutants.ts.
const mutants = (process.env['AIDLC_MUTATION'] ?? '').split(',').filter(Boolean);
const mutantTimeout = Number(process.env['AIDLC_MUTATION_EXPECT_TIMEOUT_MS'] ?? 2000);

export default defineConfig({
  testDir: '../outputs/generated-tests/subsystem',
  outputDir: '../outputs/generated-tests/test-results',
  fullyParallel: true,
  forbidOnly: true,
  retries: 0,
  reporter: [['list'], ['json']],
  use: {
    baseURL: `http://localhost:${port}`,
    viewport: { width: 800, height: 480 },
    hasTouch: true,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
  },
  projects: mutants.length
    ? mutants.map((m) => ({
        name: `mutant-${m}`,
        use: device,
        metadata: { aidlcMutant: m },
        expect: { timeout: mutantTimeout },
      }))
    : [{ name: 'front-panel', use: device }],
  webServer: {
    command: `npx ng serve --port ${port}`,
    cwd: '../..',
    url: `http://localhost:${port}`,
    reuseExistingServer: false,
    timeout: 180_000,
  },
});
